package com.erp.dao;

import com.erp.util.DBConnection;
import java.math.BigDecimal;
import java.sql.Connection;
import java.sql.Date;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** Teacher-scoped queries and writes for the teacher portal. */
public class TeacherPortalDAO {
    public long teacherId(long userId)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT id FROM teachers WHERE user_id=?")){p.setLong(1,userId);try(ResultSet r=p.executeQuery()){if(!r.next())throw new SQLException("Teacher profile was not found.");return r.getLong(1);}}}
    public Map<String,Object> profile(long userId)throws SQLException{return one("SELECT u.name,u.email,t.employee_code,t.phone,t.qualification,t.joining_date,t.department FROM users u JOIN teachers t ON t.user_id=u.id WHERE u.id=? AND u.role='TEACHER' AND u.deleted_at IS NULL",userId);}
    public List<Map<String,Object>> classes(long userId)throws SQLException{return rows("SELECT DISTINCT c.class_name,sec.section_name,ts.academic_year FROM teacher_subject ts JOIN teachers t ON t.id=ts.teacher_id JOIN sections sec ON sec.id=ts.section_id JOIN classes c ON c.id=sec.class_id WHERE t.user_id=? AND c.status=1 ORDER BY ts.academic_year DESC,c.class_name,sec.section_name",userId);}
    /** Active students enrolled in any section and academic year assigned to this teacher. */
    public List<Map<String,Object>> students(long userId)throws SQLException{return rows("SELECT s.id AS student_id,u.name,u.email,COALESCE(sc.roll_no,s.roll_no) roll_no,c.class_name,sec.section_name,sc.academic_year FROM teacher_subject ts JOIN teachers t ON t.id=ts.teacher_id JOIN student_class sc ON sc.section_id=ts.section_id AND sc.academic_year=ts.academic_year JOIN students s ON s.id=sc.student_id JOIN users u ON u.id=s.user_id JOIN sections sec ON sec.id=sc.section_id JOIN classes c ON c.id=sec.class_id WHERE t.user_id=? AND c.status=1 AND u.status=1 AND u.deleted_at IS NULL GROUP BY s.id,u.name,u.email,sc.roll_no,s.roll_no,c.class_name,sec.section_name,sc.academic_year ORDER BY c.class_name,sec.section_name,COALESCE(sc.roll_no,s.roll_no),u.name",userId);}
    public List<Map<String,Object>> assignments(long userId)throws SQLException{return rows("SELECT ts.id,ts.section_id,ts.subject_id,ts.academic_year,c.class_name,sec.section_name,sub.subject_name,sub.subject_code FROM teacher_subject ts JOIN teachers t ON t.id=ts.teacher_id JOIN sections sec ON sec.id=ts.section_id JOIN classes c ON c.id=sec.class_id JOIN subjects sub ON sub.id=ts.subject_id WHERE t.user_id=? AND c.status=1 ORDER BY ts.academic_year DESC,c.class_name,sec.section_name,sub.subject_name",userId);}
    public List<Map<String,Object>> assignmentsList(long teacherId)throws SQLException{
        List<Map<String,Object>> result=rows("SELECT a.id,a.title,a.description,a.assigned_date,a.due_date,a.status,a.academic_year,c.class_name,sec.section_name,sub.subject_name FROM assignments a JOIN sections sec ON sec.id=a.section_id JOIN classes c ON c.id=sec.class_id JOIN subjects sub ON sub.id=a.subject_id WHERE a.teacher_id=? ORDER BY a.due_date DESC,a.id DESC",teacherId);
        // Connector/J can expose MySQL TINYINT(1) as Boolean; keep the DAO's status value stable for JSPs.
        for(Map<String,Object> row:result){Object status=row.get("status");if(status instanceof Boolean)row.put("status",(Boolean)status?1:0);}
        return result;
    }
    public List<Map<String,Object>> exams(long userId)throws SQLException{return rows("SELECT e.id,e.exam_name,e.academic_year,e.exam_date,e.section_id,e.subject_id,e.results_published_at,c.class_name,sec.section_name,sub.subject_name,sub.max_marks FROM exams e JOIN sections sec ON sec.id=e.section_id JOIN classes c ON c.id=sec.class_id JOIN subjects sub ON sub.id=e.subject_id JOIN teachers t ON t.user_id=? JOIN teacher_subject ts ON ts.teacher_id=t.id AND ts.section_id=e.section_id AND ts.subject_id=e.subject_id AND ts.academic_year=e.academic_year WHERE e.status=1 ORDER BY e.exam_date DESC,e.exam_name",userId);}
    public List<Map<String,Object>> roster(long assignmentId,long userId)throws SQLException{return rows("SELECT s.id AS student_id,u.name,u.email,COALESCE(sc.roll_no,s.roll_no) roll_no FROM teacher_subject ts JOIN teachers t ON t.id=ts.teacher_id JOIN student_class sc ON sc.section_id=ts.section_id AND sc.academic_year=ts.academic_year JOIN students s ON s.id=sc.student_id JOIN users u ON u.id=s.user_id WHERE ts.id=? AND t.user_id=? AND u.status=1 AND u.deleted_at IS NULL ORDER BY u.name",assignmentId,userId);}
    public List<Map<String,Object>> attendanceFor(long assignmentId,long userId,String date,String label)throws SQLException{return rows("SELECT s.id AS student_id,u.name,COALESCE(sc.roll_no,s.roll_no) roll_no,a.status,a.remarks FROM teacher_subject ts JOIN teachers t ON t.id=ts.teacher_id JOIN student_class sc ON sc.section_id=ts.section_id AND sc.academic_year=ts.academic_year JOIN students s ON s.id=sc.student_id JOIN users u ON u.id=s.user_id LEFT JOIN attendance_sessions ats ON ats.teacher_subject_id=ts.id AND ats.attendance_date=? AND ats.session_label=? LEFT JOIN attendance a ON a.session_id=ats.id AND a.student_id=s.id WHERE ts.id=? AND t.user_id=? AND u.status=1 AND u.deleted_at IS NULL ORDER BY u.name",Date.valueOf(date),label,assignmentId,userId);}
    public void saveAttendance(long teacherId,long assignmentId,String date,String label,String[] studentIds,String[] statuses)throws SQLException{
        try(Connection c=DBConnection.getConnection()){c.setAutoCommit(false);try{Map<String,Object> scope=assignmentScope(c,teacherId,assignmentId);long sectionId=((Number)scope.get("section_id")).longValue(),subjectId=((Number)scope.get("subject_id")).longValue();String year=(String)scope.get("academic_year");long sessionId;
            try(PreparedStatement session=c.prepareStatement("INSERT INTO attendance_sessions(teacher_subject_id,attendance_date,session_label) VALUES(?,?,?) ON DUPLICATE KEY UPDATE id=LAST_INSERT_ID(id)")){session.setLong(1,assignmentId);session.setDate(2,Date.valueOf(date));session.setString(3,label);session.executeUpdate();try(PreparedStatement id=c.prepareStatement("SELECT LAST_INSERT_ID()" );ResultSet rs=id.executeQuery()){rs.next();sessionId=rs.getLong(1);}}
            try(PreparedStatement p=c.prepareStatement("INSERT INTO attendance(session_id,academic_year,student_id,teacher_id,subject_id,section_id,attendance_date,status) SELECT ?,?,?,?,?,?,?,? FROM student_class sc JOIN students s ON s.id=sc.student_id JOIN users u ON u.id=s.user_id WHERE sc.student_id=? AND sc.section_id=? AND sc.academic_year=? AND u.status=1 AND u.deleted_at IS NULL ON DUPLICATE KEY UPDATE teacher_id=VALUES(teacher_id),section_id=VALUES(section_id),status=VALUES(status)")){for(int i=0;i<studentIds.length;i++){long student=Long.parseLong(studentIds[i]);String status=statuses[i];if(!List.of("PRESENT","ABSENT","LATE","LEAVE").contains(status))throw new SQLException("Select a valid attendance status.");p.setLong(1,sessionId);p.setString(2,year);p.setLong(3,student);p.setLong(4,teacherId);p.setLong(5,subjectId);p.setLong(6,sectionId);p.setDate(7,Date.valueOf(date));p.setString(8,status);p.setLong(9,student);p.setLong(10,sectionId);p.setString(11,year);p.executeUpdate();try(PreparedStatement enrolled=c.prepareStatement("SELECT 1 FROM student_class sc JOIN students s ON s.id=sc.student_id JOIN users u ON u.id=s.user_id WHERE sc.student_id=? AND sc.section_id=? AND sc.academic_year=? AND u.status=1 AND u.deleted_at IS NULL")){enrolled.setLong(1,student);enrolled.setLong(2,sectionId);enrolled.setString(3,year);try(ResultSet rs=enrolled.executeQuery()){if(!rs.next())throw new SQLException("A selected student is not enrolled in your class.");}}}}c.commit();}catch(Exception e){c.rollback();if(e instanceof SQLException se)throw se;throw new SQLException("Attendance could not be saved.",e);}}
    }
    private Map<String,Object> assignmentScope(Connection c,long teacherId,long assignmentId)throws SQLException{try(PreparedStatement p=c.prepareStatement("SELECT section_id,subject_id,academic_year FROM teacher_subject WHERE id=? AND teacher_id=?")){p.setLong(1,assignmentId);p.setLong(2,teacherId);try(ResultSet r=p.executeQuery()){if(!r.next())throw new SQLException("Selected class and subject are not assigned to you.");Map<String,Object> m=new LinkedHashMap<>();m.put("section_id",r.getLong(1));m.put("subject_id",r.getLong(2));m.put("academic_year",r.getString(3));return m;}}}
    public long saveAssignment(long teacherId,Long id,long assignmentId,String title,String description,String assigned,String due)throws SQLException{
        try(Connection c=DBConnection.getConnection()){Map<String,Object> scope=one(c,"SELECT ts.section_id,ts.subject_id,ts.academic_year FROM teacher_subject ts WHERE ts.id=? AND ts.teacher_id=?",assignmentId,teacherId);if(scope==null)throw new SQLException("Selected class and subject are not assigned to you.");String sql=id==null?"INSERT INTO assignments(teacher_id,subject_id,section_id,academic_year,title,description,assigned_date,due_date) VALUES(?,?,?,?,?,?,?,?)":"UPDATE assignments SET subject_id=?,section_id=?,academic_year=?,title=?,description=?,assigned_date=?,due_date=? WHERE id=? AND teacher_id=?";try(PreparedStatement p=c.prepareStatement(sql,id==null?java.sql.Statement.RETURN_GENERATED_KEYS:java.sql.Statement.NO_GENERATED_KEYS)){int i=1;if(id==null)p.setLong(i++,teacherId);p.setLong(i++,((Number)scope.get("subject_id")).longValue());p.setLong(i++,((Number)scope.get("section_id")).longValue());p.setString(i++,(String)scope.get("academic_year"));p.setString(i++,title);p.setString(i++,description.isEmpty()?null:description);p.setDate(i++,Date.valueOf(assigned));p.setDate(i++,Date.valueOf(due));if(id!=null){p.setLong(i++,id);p.setLong(i,teacherId);if(p.executeUpdate()!=1)throw new SQLException("Assignment was not found.");return id;}p.executeUpdate();try(ResultSet keys=p.getGeneratedKeys()){if(keys.next())return keys.getLong(1);throw new SQLException("Assignment was saved but its id could not be read.");}}}
    }
    public Map<String,Object> assignment(long teacherId,long id)throws SQLException{return one("SELECT a.id,a.title,a.description,a.assigned_date,a.due_date,ts.id assignment_id FROM assignments a JOIN teacher_subject ts ON ts.teacher_id=a.teacher_id AND ts.subject_id=a.subject_id AND ts.section_id=a.section_id AND ts.academic_year=a.academic_year WHERE a.id=? AND a.teacher_id=?",id,teacherId);}
    public void deleteAssignment(long teacherId,long id)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("UPDATE assignments SET status=0 WHERE id=? AND teacher_id=? AND status=1")){p.setLong(1,id);p.setLong(2,teacherId);if(p.executeUpdate()!=1)throw new SQLException("Assignment was not found.");}}
    public List<Map<String,Object>> examRoster(long examId,long userId)throws SQLException{return rows("SELECT s.id student_id,u.name,COALESCE(sc.roll_no,s.roll_no) roll_no,sub.max_marks,m.marks,m.remarks FROM exams e JOIN teachers t ON t.user_id=? JOIN teacher_subject ts ON ts.teacher_id=t.id AND ts.section_id=e.section_id AND ts.subject_id=e.subject_id AND ts.academic_year=e.academic_year JOIN student_class sc ON sc.section_id=e.section_id AND sc.academic_year=e.academic_year JOIN students s ON s.id=sc.student_id JOIN users u ON u.id=s.user_id JOIN subjects sub ON sub.id=e.subject_id LEFT JOIN marks m ON m.student_id=s.id AND m.exam_id=e.id AND m.subject_id=e.subject_id WHERE e.id=? AND e.status=1 AND u.status=1 AND u.deleted_at IS NULL ORDER BY u.name",userId,examId);}
    public void saveMarks(long userId,long examId,String[] studentIds,String[] marks,String[] remarks)throws SQLException{
        try(Connection c=DBConnection.getConnection()){c.setAutoCommit(false);try{try(PreparedStatement p=c.prepareStatement("SELECT e.subject_id,sub.max_marks FROM exams e JOIN subjects sub ON sub.id=e.subject_id JOIN teachers t ON t.user_id=? JOIN teacher_subject ts ON ts.teacher_id=t.id AND ts.section_id=e.section_id AND ts.subject_id=e.subject_id AND ts.academic_year=e.academic_year WHERE e.id=? AND e.status=1")){p.setLong(1,userId);p.setLong(2,examId);try(ResultSet r=p.executeQuery()){if(!r.next())throw new SQLException("Exam is not assigned to your classes and subjects.");long subject=r.getLong(1);BigDecimal max=r.getBigDecimal(2);try(PreparedStatement w=c.prepareStatement("INSERT INTO marks(student_id,subject_id,exam_id,marks,remarks) SELECT ?,?,?,?,? FROM exams e JOIN student_class sc ON sc.student_id=? AND sc.section_id=e.section_id AND sc.academic_year=e.academic_year WHERE e.id=? ON DUPLICATE KEY UPDATE marks=VALUES(marks),remarks=VALUES(remarks)")){for(int i=0;i<studentIds.length;i++){if(marks[i]==null||marks[i].isBlank())continue;long student=Long.parseLong(studentIds[i]);BigDecimal score=new BigDecimal(marks[i]);if(score.signum()<0||score.compareTo(max)>0)throw new SQLException("Marks must be between zero and the subject maximum.");w.setLong(1,student);w.setLong(2,subject);w.setLong(3,examId);w.setBigDecimal(4,score);w.setString(5,remarks[i].isBlank()?null:remarks[i]);w.setLong(6,student);w.setLong(7,examId);w.executeUpdate();try(PreparedStatement enrolled=c.prepareStatement("SELECT 1 FROM exams e JOIN student_class sc ON sc.section_id=e.section_id AND sc.academic_year=e.academic_year JOIN students s ON s.id=sc.student_id JOIN users u ON u.id=s.user_id WHERE e.id=? AND sc.student_id=? AND u.status=1 AND u.deleted_at IS NULL")){enrolled.setLong(1,examId);enrolled.setLong(2,student);try(ResultSet check=enrolled.executeQuery()){if(!check.next())throw new SQLException("A selected student is not enrolled in this exam's class.");}}}}}}c.commit();}catch(Exception e){c.rollback();if(e instanceof SQLException se)throw se;throw new SQLException("Marks could not be saved.",e);}}
    }
    public void publishResults(long userId,long examId)throws SQLException{updateResultPublication(userId,examId,true);}
    public void unpublishResults(long userId,long examId)throws SQLException{updateResultPublication(userId,examId,false);}
    private void updateResultPublication(long userId,long examId,boolean publish)throws SQLException{
        String sql=publish?"UPDATE exams e JOIN teacher_subject ts ON ts.section_id=e.section_id AND ts.subject_id=e.subject_id AND ts.academic_year=e.academic_year JOIN teachers t ON t.id=ts.teacher_id SET e.results_published_at=CURRENT_TIMESTAMP,e.results_published_by=? WHERE e.id=? AND e.status=1 AND t.user_id=?":"UPDATE exams e JOIN teacher_subject ts ON ts.section_id=e.section_id AND ts.subject_id=e.subject_id AND ts.academic_year=e.academic_year JOIN teachers t ON t.id=ts.teacher_id SET e.results_published_at=NULL,e.results_published_by=NULL WHERE e.id=? AND e.status=1 AND t.user_id=?";
        try(Connection c=DBConnection.getConnection()){
            if(publish){try(PreparedStatement check=c.prepareStatement("SELECT COUNT(DISTINCT sc.student_id) roster,COUNT(DISTINCT m.student_id) graded FROM exams e JOIN teachers t ON t.user_id=? JOIN teacher_subject ts ON ts.teacher_id=t.id AND ts.section_id=e.section_id AND ts.subject_id=e.subject_id AND ts.academic_year=e.academic_year JOIN student_class sc ON sc.section_id=e.section_id AND sc.academic_year=e.academic_year JOIN students s ON s.id=sc.student_id JOIN users u ON u.id=s.user_id LEFT JOIN marks m ON m.exam_id=e.id AND m.student_id=s.id AND m.subject_id=e.subject_id WHERE e.id=? AND e.status=1 AND u.status=1 AND u.deleted_at IS NULL")){check.setLong(1,userId);check.setLong(2,examId);try(ResultSet r=check.executeQuery()){r.next();long roster=r.getLong("roster"),graded=r.getLong("graded");if(roster==0||roster!=graded)throw new SQLException("Enter marks for every active student before publishing results.");}}}
            try(PreparedStatement p=c.prepareStatement(sql)){if(publish){p.setLong(1,userId);p.setLong(2,examId);p.setLong(3,userId);}else{p.setLong(1,examId);p.setLong(2,userId);}if(p.executeUpdate()<1)throw new SQLException("Exam is not assigned to your teaching account.");}
        }
    }
    private Map<String,Object> one(String sql,Object... params)throws SQLException{try(Connection c=DBConnection.getConnection()){return one(c,sql,params);}}
    private Map<String,Object> one(Connection c,String sql,Object... params)throws SQLException{try(PreparedStatement p=c.prepareStatement(sql)){bind(p,params);try(ResultSet r=p.executeQuery()){if(!r.next())return null;Map<String,Object> row=new LinkedHashMap<>();int n=r.getMetaData().getColumnCount();for(int i=1;i<=n;i++)row.put(r.getMetaData().getColumnLabel(i),r.getObject(i));return row;}}}
    private List<Map<String,Object>> rows(String sql,Object... params)throws SQLException{List<Map<String,Object>> out=new ArrayList<>();try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(sql)){bind(p,params);try(ResultSet r=p.executeQuery()){int n=r.getMetaData().getColumnCount();while(r.next()){Map<String,Object> row=new LinkedHashMap<>();for(int i=1;i<=n;i++)row.put(r.getMetaData().getColumnLabel(i),r.getObject(i));out.add(row);}}}return out;}
    private void bind(PreparedStatement p,Object... values)throws SQLException{for(int i=0;i<values.length;i++){Object v=values[i];if(v instanceof Date d)p.setDate(i+1,d);else p.setObject(i+1,v);}}
} 
